function m8Bevel(g, x, y, w, h, base, hi, lo, r) { m8RR(g, x, y, w, h, r || 3, base); g.strokeStyle = hi || 'rgba(255,255,255,.18)'; g.lineWidth = 2; g.beginPath(); g.moveTo(x + 2, y + h - 2); g.lineTo(x + 2, y + 2); g.lineTo(x + w - 2, y + 2); g.stroke(); g.strokeStyle = lo || 'rgba(0,0,0,.45)'; g.beginPath(); g.moveTo(x + w - 2, y + 2); g.lineTo(x + w - 2, y + h - 2); g.lineTo(x + 2, y + h - 2); g.stroke(); }
function m8Rivets(g, x, y, w, h, step, inset) { inset = inset || 5; g.fillStyle = 'rgba(0,0,0,.4)'; const dot = function (px, py) { g.beginPath(); g.arc(px + .6, py + .6, 1.6, 0, 7); g.fill(); g.fillStyle = 'rgba(255,255,255,.22)'; g.beginPath(); g.arc(px - .3, py - .3, 1, 0, 7); g.fill(); g.fillStyle = 'rgba(0,0,0,.4)'; }; for (let i = x + inset; i <= x + w - inset; i += step) { dot(i, y + inset); dot(i, y + h - inset); } for (let j = y + inset + step; j < y + h - inset; j += step) { dot(x + inset, j); dot(x + w - inset, j); } }
function m8CylH(g, x, y, w, h, c0, c1, c2) { g.fillStyle = m8Grad(g, 0, y, 0, y + h, [[0, c1 || '#8a8e80'], [.35, c0 || '#5a5e50'], [1, c2 || '#22241e']]); m8RR(g, x, y, w, h, h / 2, g.fillStyle); }
function m8CylV(g, x, y, w, h, c0, c1, c2) { g.fillStyle = m8Grad(g, x, 0, x + w, 0, [[0, c1 || '#8a8e80'], [.35, c0 || '#5a5e50'], [1, c2 || '#22241e']]); m8RR(g, x, y, w, h, w / 2, g.fillStyle); }
function m8Disc(g, x, y, r, c0, c1) { const gr = g.createRadialGradient(x - r * .35, y - r * .35, r * .1, x, y, r); gr.addColorStop(0, c1 || '#9a9e90'); gr.addColorStop(1, c0 || '#3a3e34'); g.fillStyle = gr; g.beginPath(); g.arc(x, y, r, 0, 7); g.fill(); }
