function m8Hazard(g, x, y, w, h, a) { g.save(); g.beginPath(); g.rect(x, y, w, h); g.clip(); g.fillStyle = 'rgba(200,160,30,' + (a || .55) + ')'; g.fillRect(x, y, w, h); g.fillStyle = 'rgba(20,18,12,' + (a || .55) * 1.2 + ')'; for (let i = -h; i < w + h; i += 16) { g.beginPath(); g.moveTo(x + i, y + h); g.lineTo(x + i + 8, y + h); g.lineTo(x + i + 8 + h, y); g.lineTo(x + i + h, y); g.closePath(); g.fill(); } g.restore(); }
