function m8Tent(g, x, y, w, h) { m8SoftShadow(g, x, y, w, h, 14); g.fillStyle = m8Grad(g, 0, y, 0, y + h, [[0, '#7a7656'], [.48, '#5e5a40'], [.52, '#3a3826'], [1, '#2e2c1e']]); g.beginPath(); g.moveTo(x, y + 6); g.lineTo(x + w, y + 6); g.lineTo(x + w - 4, y + h); g.lineTo(x + 4, y + h); g.closePath(); g.fill(); g.fillRect(x, y, w, h * .5); g.strokeStyle = 'rgba(0,0,0,.35)'; g.lineWidth = 1.2; g.beginPath(); g.moveTo(x, y + h / 2); g.lineTo(x + w, y + h / 2); g.stroke(); for (let i = x + 12; i < x + w; i += 22) { g.beginPath(); g.moveTo(i, y); g.lineTo(i - 3, y + h); g.stroke(); }
    g.strokeStyle = 'rgba(200,190,150,.45)'; g.lineWidth = .8; [[x, y], [x + w, y], [x, y + h], [x + w, y + h]].forEach(function (p) { g.beginPath(); g.moveTo(p[0], p[1]); g.lineTo(p[0] + (p[0] === x ? -12 : 12), p[1] + (p[1] === y ? -10 : 10)); g.stroke(); }); m8Disc(g, x + w * .3, y + h * .3, 4, '#2a2a22', '#8a8a70'); m8Stencil(g, 'PIONIERE', x + w / 2, y + h * .78, 10, 'rgba(230,220,180,.3)'); }
